import React, { useState } from 'react';
import axios from 'axios';

function TestCasesForm() {
    const [codeSnippet, setCodeSnippet] = useState('');
    const [testCases, setTestCases] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('http://127.0.0.1:8000/app/test-cases', { codeSnippet });
            setTestCases(response.data.test_cases);
            setError('');
        } catch (err) {
            setError('Error generating test cases. Please try again later.');
            console.error(err);
        }
    };

    return (
        <div>
            <form onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="codeSnippet">Code Snippet:</label>
                    <textarea
                        id="codeSnippet"
                        value={codeSnippet}
                        onChange={(e) => setCodeSnippet(e.target.value)}
                        rows={10}
                        cols={50}
                    />
                </div>
                <button type="submit">Generate Test Cases</button>
            </form>
            {testCases && (
                <div>
                    <h3>Generated Test Cases:</h3>
                    <pre>{testCases}</pre>
                </div>
            )}
            {error && <p>{error}</p>}
        </div>
    );
}

export default TestCasesForm;
